//! Guest oneshot chat responder for OP-DBUS.
//!
//! The chatbot guest launches exactly one designated turn:
//! `op-chat-responder --turn-id %i`. This binary opens the guest's mounted
//! views, reads scoped human input, observes ZeroClaw's selected provider/model,
//! invokes the unmodified native `threetched.agent` method through mounted FUSE,
//! then commits through our `chat_response` contract.
//!
//! ZeroClaw owns provider selection, model routing, and inference. The
//! control-plane risk profile is fail-closed unless its only allowed tool is
//! `delegate`, delegation is explicitly enabled/targeted, and MCP bundles are
//! absent. Chat history and response accountability remain ours.
//!
//! Identity is the live guest kernel binding — not a CLI principal, host MQTT
//! wake, or D-Bus `ProcessPendingTurn` relay (those paths have no receiver).

use anyhow::{Context, Result, bail, ensure};
use clap::Parser;
use serde::Deserialize;
use serde_json::{Value, json};
use std::path::Path;
use tched_fs::invocation::Deadline;
use tched_fs::mounted::{GUEST_MOUNT_PATHS, MountedNamespace, declared_mount_index};
use tched_fs::namespace::MountIdentity;
use tracing::{info, warn};

const CONTROL_PLANE_AGENT: &str = "control_plane";
const MODEL_PROVIDER_PATH: &str = "agents.control_plane.model_provider";
const RISK_PROFILE_PATH: &str = "agents.control_plane.risk_profile";
const MCP_BUNDLES_PATH: &str = "agents.control_plane.mcp_bundles";
const DELEGATE_SAME_PROFILE_PATH: &str = "agents.control_plane.delegate_same_risk_profile";
const DELEGATES_PATH: &str = "agents.control_plane.delegates";
/// ZeroClaw owns provider/model selection and inference; the responder calls
/// its canonical mounted agent method.
const GENERATE_METHOD: &str = "threetched.agent";

/// Process one bridge-minted response turn inside the chatbot guest.
#[derive(Parser, Debug)]
#[command(name = "op-chat-responder")]
#[command(about = "Consume one designated turn's generation admission, generate, and commit its response")]
struct Args {
    /// Bridge-minted turn id (systemd template instance `%i`).
    #[arg(long, env = "OP_CHAT_RESPONDER_TURN_ID")]
    turn_id: String,
}

#[derive(Debug, Deserialize)]
struct PendingInput {
    turn_id: String,
    expires_at: String,
    #[allow(dead_code)]
    prompt: String,
    generation: Option<GenerationAdmission>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct BeginGenerationReceipt {
    turn_id: String,
    expires_at: String,
}


#[derive(Debug, Deserialize)]
struct GenerationAdmission {
    response_mode: String,
    prompt: String,
}

#[derive(Debug, Deserialize)]
struct ConfigJson {
    path: String,
    value: Value,
}

/// Terminal frame from our-stack generate (same shape the commit path expects).
#[derive(Debug, Deserialize)]
struct DoneFrame {
    #[serde(rename = "type")]
    kind: String,
    full_response: String,
    provider: String,
    model: String,
}

struct GuestViews {
    mounts: [MountedNamespace; 2],
}

impl GuestViews {
    fn open() -> Result<Self> {
        Ok(Self {
            mounts: [
                MountedNamespace::open_for_mode(
                    Path::new(GUEST_MOUNT_PATHS[0]),
                    &MountIdentity::GuestKernel,
                )
                .with_context(|| format!("open guest mount {}", GUEST_MOUNT_PATHS[0]))?,
                MountedNamespace::open_for_mode(
                    Path::new(GUEST_MOUNT_PATHS[1]),
                    &MountIdentity::GuestKernel,
                )
                .with_context(|| format!("open guest mount {}", GUEST_MOUNT_PATHS[1]))?,
            ],
        })
    }

    fn for_plugin(&self, plugin: &str) -> Result<&MountedNamespace> {
        let index = declared_mount_index([
            self.mounts[0].contains_plugin(plugin)?,
            self.mounts[1].contains_plugin(plugin)?,
        ])?;
        Ok(&self.mounts[index])
    }

    fn call_response(
        &self,
        plugin: &str,
        method: &str,
        arguments: Value,
        turn_id: &str,
        deadline: Deadline,
    ) -> Result<Value> {
        let mount = self.for_plugin(plugin)?;
        let decl = mount.method_decl(plugin, method)?;
        let receipt = mount
            .call_for_response(plugin, method, &decl, arguments, turn_id, deadline)
            .with_context(|| format!("mounted {plugin}.{method} for turn {turn_id}"))?;
        receipt
            .get("result")
            .cloned()
            .context("mounted receipt missing result")
    }
}

fn validate_turn_id(turn_id: &str) -> Result<()> {
    let parsed = uuid::Uuid::parse_str(turn_id).context("turn-id must be a UUID")?;
    ensure!(
        parsed.to_string() == turn_id,
        "turn-id must be the canonical UUID string"
    );
    Ok(())
}

fn process_receipt_stdout(result: &Value) -> Result<&str> {
    let exit = result
        .get("exit")
        .and_then(Value::as_i64)
        .context("foundation command receipt missing exit")?;
    ensure!(
        exit == 0,
        "foundation command exited {exit}; do not retry automatically"
    );
    result
        .get("stdout")
        .and_then(Value::as_str)
        .context("foundation command receipt missing stdout")
}

fn config_get(views: &GuestViews, path: &str, turn_id: &str) -> Result<Value> {
    let result = views.call_response(
        "threetched",
        "config.get",
        json!({
            "arguments": [path],
            "--json": true,
        }),
        turn_id,
        Deadline::ordinary(),
    )?;
    let stdout = process_receipt_stdout(&result)?;
    let parsed: ConfigJson =
        serde_json::from_str(stdout).context("config.get --json stdout is not {{path,value}}")?;
    ensure!(
        parsed.path == path,
        "config.get returned path {} for requested {path}",
        parsed.path
    );
    Ok(parsed.value)
}

fn observe_selection(views: &GuestViews, turn_id: &str) -> Result<(String, String)> {
    let provider_ref = config_get(views, MODEL_PROVIDER_PATH, turn_id)?;
    let provider_ref = provider_ref
        .as_str()
        .context("agents.control_plane.model_provider is not a string")?
        .trim();
    ensure!(
        !provider_ref.is_empty() && !provider_ref.contains('\0'),
        "control-plane model_provider is empty or invalid"
    );
    let (family, alias) = provider_ref
        .split_once('.')
        .context("model_provider must be family.alias")?;
    ensure!(
        !family.is_empty() && !alias.is_empty() && !alias.contains('.'),
        "model_provider family.alias is malformed"
    );
    let model_path = format!("providers.models.{family}.{alias}.model");
    let model = config_get(views, &model_path, turn_id)?;
    let model = model
        .as_str()
        .context("selected model path is not a string")?
        .trim()
        .to_owned();
    ensure!(!model.is_empty() && !model.contains('\0'), "selected model is empty");
    Ok((provider_ref.to_owned(), model))
}

/// ZeroClaw's native agent loop may execute tools. The control-plane root is
/// deliberately delegation-only: fail closed unless the native risk profile
/// explicitly admits only `delegate`, delegation is enabled, and neither MCP
/// bundles nor same-profile implicit delegates widen the surface.
fn ensure_delegate_only_profile(views: &GuestViews, turn_id: &str) -> Result<()> {
    let risk_profile = config_get(views, RISK_PROFILE_PATH, turn_id)?;
    let risk_profile = risk_profile
        .as_str()
        .context("agents.control_plane.risk_profile is not a string")?
        .trim();
    ensure!(
        !risk_profile.is_empty()
            && risk_profile
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'-')),
        "control-plane risk profile name is empty or invalid"
    );

    let allowed_path = format!("risk_profiles.{risk_profile}.allowed_tools");
    let allowed_tools = config_get(views, &allowed_path, turn_id)?;
    let allowed_tools = allowed_tools
        .as_array()
        .context("control-plane risk profile allowed_tools is not an array")?
        .iter()
        .map(|tool| {
            tool.as_str()
                .context("control-plane allowed_tools contains a non-string")
        })
        .collect::<Result<Vec<_>>>()?;
    ensure!(
        allowed_tools.as_slice() == ["delegate"],
        "control-plane ZeroClaw agent must allow exactly the delegate tool; refusing execution-capable profile"
    );

    let delegation_path = format!("risk_profiles.{risk_profile}.delegation_policy.mode");
    let delegation = config_get(views, &delegation_path, turn_id)?;
    ensure!(
        delegation.as_str() == Some("allow"),
        "control-plane ZeroClaw agent delegation policy is not enabled"
    );

    let mcp_bundles = config_get(views, MCP_BUNDLES_PATH, turn_id)?;
    ensure!(
        mcp_bundles.as_array().is_none_or(Vec::is_empty),
        "control-plane ZeroClaw agent must not receive MCP bundles"
    );
    let same_profile = config_get(views, DELEGATE_SAME_PROFILE_PATH, turn_id)?;
    ensure!(
        same_profile.as_bool() == Some(false),
        "control-plane ZeroClaw agent must disable implicit same-profile delegation"
    );
    let delegates = config_get(views, DELEGATES_PATH, turn_id)?;
    ensure!(
        delegates.as_array().is_some_and(|targets| !targets.is_empty()),
        "control-plane ZeroClaw agent needs an explicit delegate allowlist"
    );
    Ok(())
}

/// Run the ZeroClaw-owned one-shot agent path for one designated response.
/// ZeroClaw owns provider/model selection and inference; the response remains
/// committed through our `chat_response` contract below.
fn zeroclaw_generate(
    views: &GuestViews,
    turn_id: &str,
    prompt: &str,
    provider: &str,
    model: &str,
) -> Result<DoneFrame> {
    ensure_delegate_only_profile(views, turn_id)?;
    let result = views.call_response(
        "threetched",
        "agent",
        json!({
            "--agent": [CONTROL_PLANE_AGENT],
            "--message": [prompt],
            "--model-provider": [provider],
            "--model": [model],
        }),
        turn_id,
        Deadline::application(),
    )?;
    let full_response = process_receipt_stdout(&result)?.trim().to_owned();
    ensure!(!full_response.is_empty(), "ZeroClaw agent returned empty stdout");
    Ok(DoneFrame {
        kind: "done".into(),
        full_response,
        provider: provider.to_owned(),
        model: model.to_owned(),
    })
}

fn commit_response(
    views: &GuestViews,
    turn_id: &str,
    mode: &str,
    frame: &DoneFrame,
) -> Result<Value> {
    let (message, canvas) = match mode {
        "text" => (frame.full_response.clone(), None),
        "application" => {
            let value: Value = serde_json::from_str(&frame.full_response)
                .context("application generation did not return a JSON canvas")?;
            let canvas = value
                .as_object()
                .cloned()
                .context("application canvas must be a JSON object")?;
            ("Application ready.".to_owned(), Some(canvas))
        }
        other => bail!("unsupported response_mode {other}"),
    };

    let mut args = json!({
        "turn_id": turn_id,
        "message": message,
        "message_type": "info",
        "related_actions": [GENERATE_METHOD],
    });
    if let Some(canvas) = canvas {
        args.as_object_mut()
            .context("respond_to_user args")?
            .insert("canvas".into(), Value::Object(canvas));
    }

    views.call_response(
        "chat_response",
        "respond_to_user",
        args,
        turn_id,
        Deadline::application(),
    )
}

fn refuse(views: &GuestViews, turn_id: &str, reason: &str) -> Result<Value> {
    views.call_response(
        "chat_response",
        "cannot_perform",
        json!({
            "turn_id": turn_id,
            "reason": reason,
            "category": "not_supported",
            "alternatives": [],
        }),
        turn_id,
        Deadline::ordinary(),
    )
}

fn read_pending_turn_input(views: &GuestViews, turn_id: &str) -> Result<PendingInput> {
    let result = views.call_response(
        "chat_response",
        "get_pending_turn_input",
        json!({ "turn_id": turn_id }),
        turn_id,
        Deadline::ordinary(),
    )?;
    let pending: PendingInput =
        serde_json::from_value(result).context("invalid get_pending_turn_input result")?;
    ensure!(
        pending.turn_id == turn_id,
        "pending input turn_id differs from the guest unit instance"
    );
    Ok(pending)
}


fn process_turn(turn_id: &str) -> Result<()> {
    validate_turn_id(turn_id)?;
    let views = GuestViews::open()?;

    let pending = read_pending_turn_input(&views, turn_id)?;
    if pending.generation.is_none() {
        warn!(%turn_id, "turn has no generation admission; refusing");
        refuse(
            &views,
            turn_id,
            "this turn was not admitted for automatic generation",
        )?;
        return Ok(());
    }

    let (provider, model) = observe_selection(&views, turn_id)?;

    // This bridge-owned mutation is single-use. If the receipt is lost or
    // the turn was already admitted, never repeat native model work.
    let result = views.call_response(
        "chat_response",
        "begin_generation",
        json!({ "turn_id": turn_id }),
        turn_id,
        Deadline::ordinary(),
    )?;
    let receipt: BeginGenerationReceipt =
        serde_json::from_value(result).context("invalid begin_generation result")?;
    ensure!(
        receipt.turn_id == turn_id && receipt.expires_at == pending.expires_at,
        "generation admission receipt differs from the pending turn"
    );

    // Re-read the exact bound prompt only after the one-use admission succeeds.
    let pending = read_pending_turn_input(&views, turn_id)?;
    ensure!(
        pending.expires_at == receipt.expires_at,
        "pending turn lease changed after generation admission"
    );
    let generation = pending
        .generation
        .context("generation admission disappeared after its one-use receipt")?;

    info!(
        %turn_id,
        %provider,
        %model,
        mode = %generation.response_mode,
        method = GENERATE_METHOD,
        "ZeroClaw-owned agent generation for designated response"
    );

    match zeroclaw_generate(
        &views,
        turn_id,
        &generation.prompt,
        &provider,
        &model,
    ) {
        Ok(frame) => {
            ensure!(
                frame.kind == "done",
                "ZeroClaw agent terminal type is {}, not done",
                frame.kind
            );
            ensure!(
                frame.provider == provider && frame.model == model,
                "generation selection drifted from the observed ZeroClaw config"
            );
            ensure!(
                !frame.full_response.is_empty() && frame.full_response.len() <= 256 * 1024,
                "generation response is empty or exceeds its bound"
            );
            let committed = commit_response(&views, turn_id, &generation.response_mode, &frame)?;
            info!(%turn_id, ?committed, "response committed into the human conversation");
        }
        Err(error) => {
            let reason = format!(
                "ZeroClaw native agent generation refused or failed: {error}; required mounted method: {GENERATE_METHOD}"
            );
            warn!(%turn_id, %reason, "refusing turn via chat_response.cannot_perform");
            refuse(&views, turn_id, &reason)?;
        }
    }
    Ok(())
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let args = Args::parse();
    process_turn(&args.turn_id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use clap::Parser;

    #[test]
    fn guest_unit_turn_id_is_accepted() {
        let args = Args::try_parse_from([
            "op-chat-responder",
            "--turn-id",
            "00000000-0000-4000-8000-000000000001",
        ])
        .unwrap();
        assert_eq!(args.turn_id, "00000000-0000-4000-8000-000000000001");
        validate_turn_id(&args.turn_id).unwrap();
    }

    #[test]
    fn retired_mqtt_relay_arguments_are_rejected() {
        for retired in [
            "--principal-id",
            "--mqtt-host",
            "--mqtt-port",
            "--dbus-dest",
            "--lungs-mount",
            "--poll-interval",
            "--polling-mode",
        ] {
            let error = Args::try_parse_from([
                "op-chat-responder",
                "--turn-id",
                "00000000-0000-4000-8000-000000000001",
                retired,
            ])
            .unwrap_err();
            assert!(
                matches!(
                    error.kind(),
                    clap::error::ErrorKind::UnknownArgument
                ),
                "{retired}: {:?}",
                error.kind()
            );
        }
    }

    #[test]
    fn turn_id_is_required() {
        let error = Args::try_parse_from(["op-chat-responder"]).unwrap_err();
        assert_eq!(error.kind(), clap::error::ErrorKind::MissingRequiredArgument);
    }

    #[test]
    fn non_canonical_uuid_is_rejected() {
        assert!(validate_turn_id("not-a-uuid").is_err());
        assert!(validate_turn_id("00000000000040008000000000000001").is_err());
    }

}
